.video-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: var(--space-5);
  padding: 0 var(--space-4);
  contain: layout style;
}

.video-grid::-webkit-scrollbar {
  display: none;
}

.reel-card {
  position: relative;
  overflow: hidden;
  border-radius: 24px;
  background: var(--bg-tertiary);
  border: 1px solid var(--line-default);
  box-shadow: var(--shadow-lg);
  transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
  cursor: pointer;
  contain: layout paint;
}

/* Premium Hover Animation */
.reel-card:hover {
  transform: translateY(-8px) scale(1.02);
  box-shadow: var(--shadow-2xl);
  border-color: var(--accent-glow-strong);
}

.reel-card:active {
  transform: translateY(-4px) scale(1.01);
  transition: transform var(--transition-fast);
}

/* Video Element */
.reel-card video {
  width: 100%;
  aspect-ratio: 9 / 16;
  object-fit: contain;
  display: block;
  position: relative;
  z-index: 1;
  border-radius: 24px;
  background: var(--bg-tertiary);
}

/* Loading Skeleton */
.reel-card.loading {
  pointer-events: none;
  position: relative;
}

.reel-card.loading::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: linear-gradient(
    90deg,
    rgba(108, 77, 255, 0.04) 0%,
    rgba(108, 77, 255, 0.08) 50%,
    rgba(108, 77, 255, 0.04) 100%
  );
  background-size: 200% 100%;
  animation: shimmer 2s ease-in-out infinite;
  z-index: 5;
  border-radius: inherit;
  will-change: background-position;
}

.reel-card.loading::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--bg-tertiary);
  border-radius: inherit;
  z-index: 0;
}

@keyframes shimmer {
  0% {
    background-position: -200% 0;
  }
  100% {
    background-position: 200% 0;
  }
}

/* Ripple effect for bottom nav clicks */
@keyframes ripple {
  to {
    width: 100px;
    height: 100px;
    opacity: 0;
  }
}

.ripple {
  position: absolute;
  width: 20px;
  height: 20px;
  background: rgba(108, 77, 255, 0.3);
  border-radius: 50%;
  transform: translate(-50%, -50%);
  pointer-events: none;
  animation: ripple 0.6s ease-out;
}

