## Summary
Thoroughly explored `D:\portfouilo\photographyportfolio`. All 9 tasks complete. Below is the exact code/evidence. Key finding: video cards are 100% dynamically generated by `script.js` — there is **NO existing engagement UI** (no like/view/share buttons, no `data-slug`, no `data-video` attributes) in `index.html`. The slug system, however, is already fully wired server-side and in `videoCatalog.js`.

---

## 1. script.js — Reel/Video functions (exact code)

### `initVideoLoadingHandlers(card, video)` — L61
```js
// Attach loading-state event handlers to a reel card's video element
function initVideoLoadingHandlers(card, video) {
  if (!card || !video) return;

  video.addEventListener('loadstart', () => card.classList.add('loading'));
  video.addEventListener('loadedmetadata', () => card.classList.remove('loading'));
  video.addEventListener('loadeddata', () => card.classList.remove('loading'));
  video.addEventListener('canplay', () => card.classList.remove('loading'));
  video.addEventListener('waiting', () => card.classList.add('loading'));
  video.addEventListener('playing', () => card.classList.remove('loading'));

  // Fallback: remove loading state after 5s (iOS)
  setTimeout(() => card.classList.remove('loading'), 5000);
}
```

### `createReelCard(url)` — L227
```js
function createReelCard(url) {
  const card = document.createElement('article');
  card.className = 'reel-card';
  card.innerHTML =
    '<video controls controlsList="nodownload noplaybackrate" disablePictureInPicture playsinline webkit-playsinline preload="metadata">' +
      '<source data-src="' + url + '" type="video/mp4">' +
    '</video>';
  return card;
}
```
**NOTE:** `createReelCard` does NOT set any `data-slug` / `data-video` attribute on the card, and does NOT add any engagement buttons. It only injects a `<video>` element. The card's `data-panel` context comes from the parent grid (read in `enhanceReelCards`).

### `lazyVideoObserver` IntersectionObserver — L238
```js
// Lazy-load video sources via IntersectionObserver
const lazyVideoObserver = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      const source = entry.target.querySelector('source');
      if (source && source.dataset.src) {
        const video = entry.target.querySelector('video');
        source.src = source.dataset.src;
        source.removeAttribute('data-src');
        if (video) video.load();
      }
      lazyVideoObserver.unobserve(entry.target);
    }
  });
}, { rootMargin: '300px 0px', threshold: 0.01 });
```
Observed at: L266 (in `renderVideoCards`) and L535 (in `renderSearchResults`).

### `renderVideoCards(urls, containerId, slug, limit)` — L253
```js
function renderVideoCards(urls, containerId, slug, limit) {
  const grid = document.getElementById(containerId);
  if (!grid) return;

  const list = limit ? urls.slice(0, limit) : urls;
  const fragment = document.createDocumentFragment();

  list.forEach(url => {
    const card = createReelCard(url);
    fragment.appendChild(card);

    const video = card.querySelector('video');
    initVideoLoadingHandlers(card, video);
    lazyVideoObserver.observe(card);

    card.classList.add('reveal-scale');
    const delay = Math.min(Math.floor(fragment.children.length / 3), 5);
    card.classList.add('reveal-delay-' + (delay + 1));
    revealObserver.observe(card);
  });

  grid.innerHTML = '';
  grid.appendChild(fragment);

  enhanceReelCards();
  forceActivateRevealCards(grid);
}
```
**NOTE:** The `slug` parameter is passed in but **never used inside the function**. The category label is instead derived in `enhanceReelCards()` from `grid.dataset.panel`.

### `renderSearchResults(query)` — L490
```js
function renderSearchResults(query) {
  const resultsContainer = document.getElementById('video-search-results');
  const grid = document.getElementById('search-results-grid');
  const countEl = document.getElementById('search-results-count');
  const noResultsEl = document.getElementById('search-no-results');
  const featuredPreviews = document.querySelectorAll('.featured-preview');

  if (!resultsContainer || !grid) return;

  if (!query || query.trim() === '') {
    resultsContainer.hidden = true;
    if (noResultsEl) noResultsEl.hidden = true;
    featuredPreviews.forEach(el => el.style.display = '');
    return;
  }

  const q = query.toLowerCase().trim();
  const results = searchIndex.filter(item =>
    (item.title || '').toLowerCase().includes(q)
  );

  featuredPreviews.forEach(el => el.style.display = 'none');
  resultsContainer.hidden = false;

  if (countEl) {
    countEl.textContent = results.length + ' result' + (results.length !== 1 ? 's' : '') + ' for "' + query.trim() + '"';
  }

  grid.innerHTML = '';

  if (results.length === 0) {
    if (noResultsEl) noResultsEl.hidden = false;
    return;
  }

  if (noResultsEl) noResultsEl.hidden = true;

  const fragment = document.createDocumentFragment();

  results.forEach(item => {
    const card = createReelCard(item.video);
    fragment.appendChild(card);

    const video = card.querySelector('video');
    initVideoLoadingHandlers(card, video);
    lazyVideoObserver.observe(card);

    card.classList.add('reveal-scale');
    const delay = Math.min(Math.floor(fragment.children.length / 3), 5);
    card.classList.add('reveal-delay-' + (delay + 1));
    revealObserver.observe(card);
  });

  grid.appendChild(fragment);
  enhanceReelCards();
  forceActivateRevealCards(grid);

  // Set correct category tag per card (enhanceReelCards uses grid's data-panel)
  grid.querySelectorAll('.reel-card').forEach((card, i) => {
    const tag = card.querySelector('.reel-tag');
    if (tag) {
      tag.textContent = categoryLabels[results[i].category] || results[i].category;
    }
  });
}
```
**NOTE:** In search, the tag is corrected per-card AFTER `enhanceReelCards()` because the search grid's `data-panel` is `"search"` (not a real category). Each search result item carries `item.category` (the slug). This is the closest existing place where per-card category/slug data is available.

### `enhanceReelCards()` — L1116
```js
function enhanceReelCards() {
  document.querySelectorAll('.reel-card').forEach(card => {
    if (card.querySelector('.reel-overlay')) return;

    const grid = card.closest('.video-grid');
    const panel = grid ? (grid.dataset.panel || '').replace('-full', '') : '';
    const label = categoryLabels[panel] || '';

    const overlay = document.createElement('div');
    overlay.className = 'reel-overlay';
    overlay.innerHTML =
      '<span class="reel-tag">' + label + '</span>' +
      '<div class="reel-play-btn">' +
        '<svg viewBox="0 0 24 24" fill="currentColor"><polygon points="5 3 19 12 5 21 5 3"></polygon></svg>' +
      '</div>' +
      '<div class="reel-gradient"></div>';

    card.appendChild(overlay);

    const video = card.querySelector('video');
    if (video) {
      video.addEventListener('play', () => card.classList.add('playing'));
      video.addEventListener('pause', () => card.classList.remove('playing'));
      video.addEventListener('ended', () => card.classList.remove('playing'));
    }
  });
}
```
**NOTE:** This is the single place that builds the overlay markup (`.reel-overlay`, `.reel-tag`, `.reel-play-btn`, `.reel-gradient`). Any engagement UI (like/share/view buttons) would logically be added here or in `createReelCard`. It is idempotent (skips cards that already have `.reel-overlay`).

### Related helpers (for context)
- `forceActivateRevealCards(grid)` — L283 (iOS Safari reveal fix; adds `.active` to in-viewport reveal elements).
- `loadVideoCategories()` — calls `renderVideoCards(urls, 'home-grid-<slug>', cat.slug, 3)` and `renderVideoCards(urls, 'grid-cat-<slug>', cat.slug)` per category.
- Search index built in `getSearchIndex()` (L460): each item = `{ title, video, category }` where `title` = `decodeURIComponent(url.split('/').pop())`. **No slug is stored in the search index** — only the raw `video` URL and `category` slug.

