      const urls = await fetchCategoryUrls(cat.txt);
      return urls.map(url => ({
        title: decodeURIComponent(url.split('/').pop() || '') || url,
        video: url,
        category: cat.slug
      }));
    })
  );

  searchIndex = results.flat();
  return searchIndex;
}

